package io.floci.aws.services.eventbridgev2;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.node.ObjectNode;
import io.floci.aws.core.common.RequestConstraintCheck;
import io.floci.aws.core.common.SmithyValidationErrors;

import java.util.List;

/**
 * Checks EventBridge V2 event source requests against the constraints generated by
 * {@code tools/aws/regen_eventbridgev2_shapes.py}. Every violation is answered together as
 * {@code InvalidInputException}, in the wording AWS uses.
 */
final class EventBridgeV2RequestShapes {

    private static final RequestConstraintCheck CHECK = RequestConstraintCheck.load(
            "aws/eventbridgev2-request-shapes.json", "EventBridge V2 request shapes",
            RequestConstraintCheck.standardMessages("InvalidInputException"));

    private EventBridgeV2RequestShapes() {
    }

    static void check(String operation, JsonNode request) {
        List<String> violations = CHECK.violations(operation, withoutWhsecPrefix(request));
        if (!violations.isEmpty()) {
            throw SmithyValidationErrors.exception("InvalidInputException", violations);
        }
    }

    /** AWS judges the length of a Base64 HMAC secret without its {@code whsec_} prefix. */
    private static JsonNode withoutWhsecPrefix(JsonNode request) {
        JsonNode hmac = request.path("Configuration").path(WebhookEventsConfigurations.WEBHOOK)
                .path("AuthConfiguration").path(WebhookEventsConfigurations.HMAC);
        String secret = WebhookEventsConfigurations.hmacSecretValue(hmac);
        if (secret == null || secret.equals(hmac.path("SecretValue").textValue())) {
            return request;
        }
        ObjectNode copy = request.deepCopy();
        ((ObjectNode) copy.path("Configuration").path(WebhookEventsConfigurations.WEBHOOK)
                .path("AuthConfiguration").path(WebhookEventsConfigurations.HMAC)).put("SecretValue", secret);
        return copy;
    }
}
